FPS = 14.97340425531915
FRAME_DURATION = 1.0 / FPS

def play():
    print("[+] Lancement de la lecture en boucle (Ctrl+C pour quitter)...")
    time.sleep(1)
    
    sys.stdout.write("\033[?25l")
    sys.stdout.flush()

    try:
        while True:
            start_loop = time.perf_counter()
            for i, frame in enumerate(FRAMES):
                frame_start = time.perf_counter()
                
                sys.stdout.write("\033[H" + frame)
                sys.stdout.flush()
                
                target = start_loop + (i + 1) * FRAME_DURATION
                sleep_time = target - time.perf_counter()
                if sleep_time > 0:
                    time.sleep(sleep_time)
    except KeyboardInterrupt:
        pass
    finally:
        sys.stdout.write("\033[?25h\033[0m\n")
        print("\nArrêt de la lecture.")

if __name__ == "__main__":
    play()
